={{ (() => {
  const data = $json;
  const body = {
    model: data.model,
    max_tokens: data.max_tokens,
    messages: data.messages,
    container: data.container,
    tools: data.tools
  };
  if (data.system) body.system = data.system;
  return JSON.stringify(body);
})() }}

