// ============================================
// EXTRACT FILE IDs FROM RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

// Handle API error
if (input.error) {
  return {
    success: false,
    error: {
      code: input.error.type || 'ANTHROPIC_ERROR',
      message: input.error.message || 'Anthropic Skills API error',
      http_status: 500
    },
    metadata: prevData.metadata,
    api_key: prevData.api_key
  };
}

// Extract text content and file references
const textContent = [];
const fileRefs = [];

for (const block of (input.content || [])) {
  if (block.type === 'text') {
    textContent.push(block.text);
  }
  // Check for tool_use blocks that might contain file references
  if (block.type === 'tool_use' && block.name === 'create_document') {
    // The file_id will be in the subsequent tool_result
    // or in the container's file output
  }
}

// Check for files in container output
if (input.container_result?.files) {
  for (const file of input.container_result.files) {
    fileRefs.push({
      file_id: file.file_id,
      name: file.name,
      mime_type: file.mime_type,
      size: file.size
    });
  }
}

// Alternative: Check content blocks for file artifacts
for (const block of (input.content || [])) {
  if (block.type === 'tool_result' && block.output?.file_id) {
    fileRefs.push({
      file_id: block.output.file_id,
      name: block.output.name || 'document',
      mime_type: block.output.mime_type || 'application/octet-stream'
    });
  }
}

return {
  success: true,
  has_files: fileRefs.length > 0,
  file_refs: fileRefs,
  text_content: textContent.join('\n'),
  raw_response: input,
  model: input.model || prevData.model,
  usage: input.usage || { input_tokens: 0, output_tokens: 0 },
  stop_reason: input.stop_reason || 'end_turn',
  metadata: prevData.metadata,
  api_key: prevData.api_key,
  startTime: startTime
};

// ============================================
// DOWNLOAD FILES FROM ANTHROPIC FILES API
// Aligned with contract §3.4 (filename, size_bytes)
// ============================================

const data = $json;
const files = [];

// For each file reference, build download info
// Using the Anthropic Files API: GET /v1/files/{file_id}/content
for (const fileRef of data.file_refs) {
  try {
    const fileUrl = `https://api.anthropic.com/v1/files/${fileRef.file_id}/content`;

    // Contract §3.4 compliant: filename, size_bytes, download_url
    files.push({
      file_id: fileRef.file_id,
      filename: fileRef.name,           // Aligned: name → filename
      mime_type: fileRef.mime_type,
      size_bytes: fileRef.size || 0,    // Aligned: size → size_bytes
      download_url: fileUrl
    });
  } catch (error) {
    files.push({
      file_id: fileRef.file_id,
      error: error.message
    });
  }
}

const latencyMs = Date.now() - (data.startTime || Date.now());

return {
  success: true,
  content: [
    {
      type: 'text',
      text: data.text_content
    }
  ],
  files: files,
  provider: 'anthropic',
  model: data.model,
  usage: data.usage,
  stop_reason: data.stop_reason,
  metadata: data.metadata,
  _trace: {
    provider: 'anthropic',
    model: data.model,
    latency_ms: latencyMs,
    files_count: files.length
  }
};

// ============================================
// FORMAT RESPONSE WITHOUT FILES
// ============================================

const data = $json;
const latencyMs = Date.now() - (data.startTime || Date.now());

return {
  success: data.success !== false,
  content: [
    {
      type: 'text',
      text: data.text_content || ''
    }
  ],
  files: [],
  provider: 'anthropic',
  model: data.model,
  usage: data.usage || { input_tokens: 0, output_tokens: 0 },
  stop_reason: data.stop_reason || 'end_turn',
  metadata: data.metadata,
  error: data.error || null,
  _trace: {
    provider: 'anthropic',
    model: data.model,
    latency_ms: latencyMs,
    files_count: 0
  }
};
